//! Prerequisites of the pin's private meta declarations for local source grammar.
//!
//! Native descriptions and quoted templates do not synthesize the declarations
//! normally generated by Lean. Before using that representation in a module,
//! verify its actual imported parser algebra and Macro/MacroM interfaces. An
//! ordinary header alone is not authority: a source file named Init can omit or
//! replace any of these declarations.

use super::{Environment, Expr, Name, data, name, parsers};
use crate::{Budget, EngineExecutionError, Outcome};
use fln_core::expr::BinderInfo;
use fln_core::level::Level;
use fln_env::constants::{ConstantInfo, DefinitionSafety};
use fln_kernel::verdict::Verdict;
use std::collections::BTreeSet;

const STEPS: usize = 1 << 16;

fn unsupported() -> EngineExecutionError {
    EngineExecutionError::NotImplemented {
        feature: "module-system local grammar without the imported ParserDescr and Macro meta interfaces",
    }
}

fn constant(spelling: &str) -> Expr {
    Expr::const_(name(spelling), Vec::new())
}

fn conversion(
    environment: &Environment,
    left: &Expr,
    right: &Expr,
) -> Result<(), EngineExecutionError> {
    match fln_kernel::check_def_eq(
        environment,
        &[],
        left,
        right,
        Budget::for_stack_bytes(2 * 1024 * 1024),
    ) {
        Outcome::Complete(Verdict::Accepted { .. }) => Ok(()),
        Outcome::Complete(_) => Err(unsupported()),
        Outcome::Inconclusive(reason) => Err(EngineExecutionError::CouncilNoAnswer {
            summary: format!(
                "local source grammar prerequisite conversion did not complete: {reason:?}"
            ),
        }),
        Outcome::InternalFault(fault) => Err(EngineExecutionError::ImportedMacro {
            message: format!(
                "local source grammar prerequisite conversion failed internally: {fault:?}"
            ),
            disposition: ("internal-fault", false, 4),
        }),
    }
}

pub(crate) fn check_local_grammar_prerequisites(
    environment: &Environment,
) -> Result<(), EngineExecutionError> {
    let families = [
        (
            parsers::PARSER_DESCR_TYPE,
            parsers::PARSER_DESCR_CONSTRUCTOR_FIELDS,
        ),
        ("Lean.Name", parsers::PARSER_NAME_CONSTRUCTOR_FIELDS),
        ("Nat", parsers::PARSER_NAT_CONSTRUCTOR_FIELDS),
        ("Bool", parsers::PARSER_BOOL_CONSTRUCTOR_FIELDS),
    ];
    let mut allowed = BTreeSet::new();
    for (family, constructors) in families {
        allowed.insert(name(family));
        for (constructor, fields) in constructors {
            allowed.insert(name(constructor));
            allowed.extend(fields.iter().map(|field| name(field)));
        }
    }
    for (alias, target) in parsers::PARSER_TYPE_ALIASES {
        allowed.extend([name(alias), name(target)]);
    }
    let mut reader = data::Reader::new(
        environment,
        &allowed,
        data::DataLimits {
            max_steps: STEPS,
            max_depth: 64,
            max_bytes: 1 << 20,
        },
    );
    let data_error = |error| match error {
        data::DataError::Resource(resource) => EngineExecutionError::SourceScopeLimit {
            resource,
            limit: match resource {
                "parser-description data depth" => 64,
                "parser-description data bytes" => 1 << 20,
                _ => STEPS,
            },
        },
        _ => unsupported(),
    };
    for (family, constructors) in families {
        reader
            .validate_family(&name(family), constructors)
            .map_err(data_error)?;
    }
    reader
        .expected_type(parsers::TRAILING_PARSER_DESCR_TYPE)
        .map_err(data_error)?;

    // These are abbreviations in Init.Prelude. Require their real safe bodies
    // and check their interfaces against the environment's actual ReaderT and
    // EStateM; a same-named axiom cannot supply this source capability. This
    // checks prerequisites, not the compilation of generated MacroM programs.
    let mut definitions = Vec::new();
    for spelling in ["Lean.MacroM", "Lean.Macro"] {
        let Some(ConstantInfo::Defn(definition)) = environment.find(&name(spelling)) else {
            return Err(unsupported());
        };
        if definition.safety != DefinitionSafety::Safe || !definition.base.level_params.is_empty() {
            return Err(unsupported());
        }
        definitions.push(definition);
    }
    let macro_m_type = Expr::forall_e(
        Name::anonymous(),
        Expr::sort(Level::one()),
        Expr::sort(Level::one()),
        BinderInfo::Default,
    );
    conversion(environment, &definitions[0].base.type_, &macro_m_type)?;
    conversion(
        environment,
        &definitions[1].base.type_,
        &Expr::sort(Level::one()),
    )?;
    let state_monad = Expr::app(
        Expr::app(
            Expr::const_(name("EStateM"), vec![Level::zero()]),
            constant("Lean.Macro.Exception"),
        ),
        constant("Lean.Macro.State"),
    );
    let macro_m = Expr::app(
        Expr::app(
            Expr::const_(name("ReaderT"), vec![Level::zero(), Level::zero()]),
            constant("Lean.Macro.Context"),
        ),
        state_monad,
    );
    conversion(environment, &definitions[0].value, &macro_m)?;
    let macro_type = Expr::forall_e(
        Name::anonymous(),
        constant("Lean.Syntax"),
        Expr::app(constant("Lean.MacroM"), constant("Lean.Syntax")),
        BinderInfo::Default,
    );
    conversion(environment, &definitions[1].value, &macro_type)
}
